	return {
		title: "Your response",
		summary: topic?.trim()
			? `${answers.length === 1 ? "Answer" : `${answers.length} answers`} submitted for ${topic.trim()}.`
			: `${answers.length === 1 ? "Answer" : `${answers.length} answers`} submitted.`,
		items: answers.map((answer, index) => ({
