  27		const id = options.id ?? fallbackId;
  28		const runId = options.runId ?? id();
  29		let sequence = Math.max(-1, ...options.store.replay(options.sessionId).events.map((event) => event.sequence));
  30	
  31		const accept = (event: ConversationEvent) => {
  32			if (!isConversationEvent(event) || event.sessionId !== options.sessionId || event.runId !== runId) return false;
  33			const replay = options.store.replay(options.sessionId).events;
  34			if (event.sequence <= sequence || replay.some((stored) => stored.id === event.id)) return false;
  35			if (event.type === "ui.document.upserted") {
  36				const current = replayConversation(replay).uiDocuments[event.payload.document.id];
  37				if (current && current.revision >= event.payload.document.revision) return false;
  38			}
  39			if (event.type === "ui.action") {
  40				const action = event.payload.action;
  41				const state = replayConversation(replay);
  42				const document = state.uiDocuments[action.documentId];
  43				if (!document || document.revision !== action.documentRevision) return false;
  44				if (state.uiActions.some((stored) => stored.id === action.id)) return false;
  45			}
  46			const appended = options.store.append(event).appended;
  47			if (appended) sequence = event.sequence;
  48			return appended;
  49		};
  50	
  51		return {
  52			sessionId: options.sessionId,
  53			emit(type, payload) {
  54				const event = conversationEvent(type, payload, {
  55					id: id(),
  56					sequence: sequence + 1,
  57					timestamp: now().toISOString(),
  58					 sessionId: options.sessionId,
  59					runId,
  60				});
  61				const canonicalEvent: ConversationEvent = event;
  62				const accepted = accept(canonicalEvent);
  63				if (!accepted) throw new Error(`Rejected invalid ${type} event`);
  64				if (canonicalEvent.type === "ui.action") {
  65					options.store.putPendingAction({ sessionId: canonicalEvent.sessionId, runId: canonicalEvent.runId, action: canonicalEvent.payload.action, createdAt: canonicalEvent.timestamp });
  66				}
  67				return event as EventOfType<typeof type>;
  68			},
  69			accept,
  70			replay: () => replayConversation(options.store.replay(options.sessionId).events),
  71			pendingActions: () => options.store.listPendingActions(options.sessionId),
  72			resolveAction: (actionId) => options.store.removePendingAction(options.sessionId, actionId),
  73		};
  74	}
